export type ScreenVerdict = "채택" | "조건부" | "시계 한정" | "기각" | "판정 불가";

/** Equity curve of the rule (and of buy-and-hold) as fractions; a null point carries the last value. */
export interface ScreenCurve {
	t: number[];
	rule: (number | null)[];
	hold: (number | null)[];
}

export interface ScreenTrial {

