			: changed
				? "시험 연도마다 학습 부호가 달라 한 방향으로 읽을 수 없다. 기준 위면 학습 부호의 방향을 따른다."
				: `학습 부호가 ${sign < 0 ? "음수" : "양수"}라 기준 위면 ${side(long)}, 아래면 ${side(!long)}이다.`;
	const bp = Math.round(doc.cost_per_side * 1e4);
	const tiles: ScreenRuleTile[] = [
