import { describe, expect, it } from "vitest";
import {
	curveView,
	dateLabel,
	niceTicks,
	screenRule,
	trialAt,
	type ScreenDoc,
	type ScreenFeature,
	type ScreenTrial,
} from "./screen";

const trial = (over: Partial<ScreenTrial> = {}): ScreenTrial =>
	({ h: 4, train_sign: 1, folds: [{ year: 2022, ic: 0.1, n: 100, train_sign: 1 }], ...over }) as ScreenTrial;
const feature = (over: Partial<ScreenFeature> = {}): ScreenFeature =>
	({
		code: "M1",
		feature: "mimic_score",
		lead_h: 4,
		trials: [trial({ h: 1 }), trial({ h: 4 })],
		...over,
	}) as ScreenFeature;
const doc = (over: Partial<ScreenDoc> = {}): ScreenDoc =>
	({ unit: "H", cost_per_side: 0.001, fixed_sign: null, regime: null, ...over }) as ScreenDoc;

describe("screen curve", () => {
	it("picks round ticks that include zero", () => {
		expect(niceTicks(-375, 136)).toEqual([-300, -200, -100, 0, 100]);
		expect(niceTicks(0, 90)).toEqual([0, 20, 40, 60, 80]);
	});

	it("labels dates with dots so the chart never reads a day 01 as a January tick", () => {
		expect(dateLabel(Date.UTC(2022, 0, 1))).toBe("2022.01.01");
		expect(dateLabel(Date.UTC(2022, 0, 1)).endsWith("-01")).toBe(false);
	});

	it("turns the fraction sums into percent and carries over a missing point", () => {
		const t = [1, 2, 3].map((k) => Date.UTC(2022, 0, k));
		const view = curveView(trial({ curve: { t, rule: [0, null, -3.75], hold: [0, 0.5, 1.36] } }));
		expect(view?.rule).toEqual([0, 0, -375]);
		expect(view?.hold[2]).toBeCloseTo(136);
		expect(view?.ticks).toContain(0);
		expect(view?.labels).toHaveLength(3);
	});

	it("has no view without a curve or with fewer than two points", () => {
		expect(curveView(undefined)).toBeNull();
		expect(curveView(trial())).toBeNull();
		expect(curveView(trial({ curve: null }))).toBeNull();
		expect(curveView(trial({ curve: { t: [1], rule: [0], hold: [0] } }))).toBeNull();
	});

	it("falls back to the lead trial for a horizon the feature lacks", () => {
		const f = feature();
		expect(trialAt(f, 1).h).toBe(1);
		expect(trialAt(f, "lead").h).toBe(4);
		expect(trialAt(f, 24).h).toBe(4);
	});
});

describe("screen rule tiles", () => {
	const byId = (tiles: ReturnType<typeof screenRule>, id: string) => tiles.find((x) => x.id === id)!;

	it("reads a fixed-sign document as 'above 0 follows the value'", () => {
		const tiles = screenRule(doc({ fixed_sign: 1 }), feature(), trial());
		expect(tiles.map((x) => x.group)).toEqual(["entry", "entry", "fill", "exit"]);
		expect(byId(tiles, "direction")).toMatchObject({ name: "기준 위면 롱", label: "순방향" });
		expect(byId(tiles, "direction").tip).toContain("+1로 고정");
		expect(byId(tiles, "fill").name).toBe("편도 10bp");
		expect(byId(tiles, "hold").name).toBe("4H 보유");
	});

	it("flips the sides when the train sign is negative and says so when the sign changed by year", () => {
		const contrarian = screenRule(doc(), feature(), trial({ train_sign: -1 }));
		expect(byId(contrarian, "direction")).toMatchObject({ name: "기준 위면 숏", label: "역추세" });
		const changed = screenRule(
			doc(),
			feature(),
			trial({
				folds: [
					{ year: 2022, ic: 0.1, n: 100, train_sign: 1 },
					{ year: 2023, ic: 0.1, n: 100, train_sign: -1 },
				],
			}),
		);
		expect(byId(changed, "direction").label).toBe("부호 바뀜");
	});

	it("adds the regime tile only for a down-regime gate and marks a reference row", () => {
		expect(screenRule(doc({ regime: "down" }), feature(), trial()).map((x) => x.id)).toContain("regime");
		expect(screenRule(doc(), feature(), trial()).map((x) => x.id)).not.toContain("regime");
		expect(byId(screenRule(doc(), feature({ tradeable: false }), trial()), "indicator").label).toBe("참고 지표");
	});
});

// Leading-indicator screening experiments (plan 261109 S7), served by quantd as
// GET /api/v1/research/screens[/{id}]. Verdicts, gate results and the flow come from quant-signal
// verbatim; this module only names and formats them.
import type { Gate, GateFlowStep, RunMatrix, Verdict } from "./data";

export type ScreenVerdict = "채택" | "조건부" | "시계 한정" | "기각" | "판정 불가";

export interface ScreenTrial {
	h: number;
	oos_obs: number;
	oos_years: number;
	fold_sign_agree: number | null;
	ic: number | null;
	t_nw: number | null;
	ci_lo: number | null;
	ci_hi: number | null;
	partial_ic: number | null;
	ic_up: number | null;
	ic_down: number | null;
	ann_ret: number | null;
	sharpe: number | null;
	exposure: number | null;
	dsr: number | null;
	pass: boolean;
	miss: string;
	miss_gate: number | null;
	train_sign: number;
	folds: { year: number; ic: number | null; n: number; train_sign: number }[];
}

export interface ScreenFeature {
	code: string;
	feature: string;
	family: string;
	verdict: ScreenVerdict;
	reason: string;
	lead_h: number;
	tradeable?: boolean;
	test_years?: [number, number];
	trials: ScreenTrial[];
}

export interface ScreenDoc {
	experiment_id: string;
	market: string;
	title: string;
	hypothesis: string;
	sealed_at: string;
	note: string;
	unit: "D" | "H";
	horizons: number[];
	swing_horizons: number[];
	test_years: [number, number];
	regime: string | null;
	fixed_sign: number | null;
	cost_per_side: number;
	gates: { id: string; name: string; rule: string; threshold: number }[];
	gate_status: { id: string; status: Gate["status"]; reason: string }[];
	gate_flow: GateFlowStep[];
	state: "연구통과" | "평가완료" | "연구기각";
	trials_total: number;
	trials_counted: number;
	asof_violations: number;
	gate_sha256: string;
	result_hash: string;
	features: ScreenFeature[];
}

export interface ScreenSummary {
	id: string;
	market: string;
	title: string;
	state: ScreenDoc["state"];
	hypothesis: string;
	sealedAt: string;
	unit: "D" | "H";
	candidates: number;
	trialsTotal: number;
	trialsCounted: number;
	verdicts: Partial<Record<ScreenVerdict, number>>;
	resultHash: string;
	gateSha256: string;
}

/** Display name and one-line definition of each indicator (the screen's own names stay as the source). */
export const FEATURE_LABEL: Record<string, [string, string]> = {
	mom_5: ["5일 모멘텀", "5일 로그 수익률"],
	mom_21: ["21일 모멘텀", "21일 로그 수익률"],
	vol_21: ["21일 변동성", "일간 수익률 21일 표준편차"],
	volume_z90: ["거래량 z", "24시간 거래량(로그)의 90일 z점수"],
	funding_1d: ["펀딩 1일", "Binance 무기한 펀딩비 24시간 평균"],
	funding_7d: ["펀딩 7일", "펀딩비 7일 평균"],
	funding_z90: ["펀딩 z", "펀딩 1일의 90일 z점수"],
	premium_1d: ["베이시스 1일", "무기한 가격의 지수 대비 프리미엄 24시간 평균"],
	premium_z90: ["베이시스 z", "베이시스 1일의 90일 z점수"],
	oi_chg_1d: ["OI 1일 변화", "미결제약정 1일 로그 변화"],
	oi_chg_7d: ["OI 7일 변화", "미결제약정 7일 로그 변화"],
	oi_x_trend_7d: ["OI × 추세", "OI 7일 변화에 7일 가격 방향 부호를 곱한 값"],
	top_position_ls_z90: ["상위 트레이더 롱숏 z", "상위 계정 포지션 롱숏비의 90일 z점수"],
	global_ls_z90: ["전체 롱숏 z", "전체 계정 롱숏비의 90일 z점수"],
	taker_ratio_7d: ["테이커 매수비 7일", "테이커 매수/매도 거래량 비 7일 평균"],
	kimchi_1d: ["김프 1일", "업비트 원화가 ÷ (바이낸스가 × 원달러) − 1"],
	kimchi_7d: ["김프 7일", "김프 1일의 7일 평균"],
	kimchi_z180: ["김프 z", "김프 1일의 180일 z점수"],
	follow_next: [
		"그의 방향 따라가기",
		"직전 칸의 순진입 방향(롱 +, 숏 −)을 한 칸 늦게 따라간다. 체결이 실시간 공개되지 않으므로 참고 행이다",
	],
