/** The trial at horizon `h`; "lead" or a horizon the feature lacks falls back to the lead trial. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

/** Round ticks at 1·2·5 × 10ⁿ and keep 0 whenever the range crosses it. */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [];
	const lo = Math.min(min, max);
	const hi = Math.max(min, max);
	if (lo === hi) return [lo];
	const rough = (hi - lo) / 5;
	const magnitude = 10 ** Math.floor(Math.log10(rough));
	const norm = rough / magnitude;
	const step = (norm <= 1.5 ? 1 : norm <= 3 ? 2 : norm <= 7 ? 5 : 10) * magnitude;
	const round = (v: number) => Math.round(v * 1e9) / 1e9;
	const eps = step * 1e-9;
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + eps; v += step) ticks.push(round(v));
	if (lo <= 0 && hi >= 0 && !ticks.some((v) => Math.abs(v) <= eps)) {
		ticks.push(0);
		ticks.sort((a, b) => a - b);
	}
