}

const toPercent = (v: number) => Math.round(v * 100 * 1e6) / 1e6;

/** Fraction sums as percent; a missing point keeps the previous value so the line never dives to 0. */
function carryPercent(values: (number | null)[] | undefined): number[] {
	let last = 0;
