 export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

+/** The trial at horizon `h`; "lead" or a horizon the feature lacks falls back to the lead trial. */
+export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
+	if (h === "lead") return leadTrial(f);
+	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
+}
+
+/** Round ticks at 1·2·5 × 10ⁿ and keep 0 whenever the range crosses it. */
+export function niceTicks(min: number, max: number): number[] {
+	if (!Number.isFinite(min) || !Number.isFinite(max)) return [];
+	const lo = Math.min(min, max);
+	const hi = Math.max(min, max);
+	if (lo === hi) return [lo];
+	const rough = (hi - lo) / 5;
+	const magnitude = 10 ** Math.floor(Math.log10(rough));
+	const norm = rough / magnitude;
+	const step = (norm <= 1.5 ? 1 : norm <= 3 ? 2 : norm <= 7 ? 5 : 10) * magnitude;
+	const round = (v: number) => Math.round(v * 1e9) / 1e9;
+	const eps = step * 1e-9;
+	const ticks: number[] = [];
+	for (let v = Math.ceil(lo / step) * step; v <= hi + eps; v += step) ticks.push(round(v));
+	if (lo <= 0 && hi >= 0 && !ticks.some((v) => Math.abs(v) <= eps)) {
+		ticks.push(0);
+		ticks.sort((a, b) => a - b);
+	}
+	return ticks;
+}
+
+/** Dotted date so a January tick (`.01.`) can never be mistaken for a day (test: no `-01`). */
+export function dateLabel(ts: number): string {
+	const d = new Date(ts);
+	const pad = (v: number) => String(v).padStart(2, "0");
+	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
+}
+
+const toPercent = (v: number) => Math.round(v * 100 * 1e6) / 1e6;
+
+/** Fraction sums as percent; a missing point keeps the previous value so the line never dives to 0. */
+function carryPercent(values: (number | null)[] | undefined): number[] {
+	let last = 0;
+	return (values ?? []).map((v) => {
+		if (v != null && Number.isFinite(v)) last = toPercent(v);
+		return last;
+	});
+}
+
+export interface CurveView {
