+	hold: number[];
+	ticks: number[];
+}
+
+/** Chart-ready view of a trial's curve, or null when there is nothing to draw (fewer than two points). */
+export function curveView(trial: ScreenTrial | null | undefined): CurveView | null {
+	const c = trial?.curve;
+	if (!c?.t || c.t.length < 2) return null;
+	const rule = carryPercent(c.rule);
+	const hold = carryPercent(c.hold);
+	const all = [...rule, ...hold];
+	if (!all.length) return null;
+	return {
+		t: c.t,
+		labels: c.t.map(dateLabel),
+		rule,
+		hold,
+		ticks: niceTicks(Math.min(...all), Math.max(...all)),
+	};
+}
